#include <stdio.h>
#define SEC_PER_MIN 60
int main(void)
{
int sec, min, left;
printf("Enter the number of seconds (<=0 to quit):\n");
scanf("%d", &sec);
while (sec > 0)
{
min = sec / SEC_PER_MIN;
left = sec % SEC_PER_MIN;
printf("%d seconds is %d minutes, %d seconds.\n", sec, min, left);
printf("Enter next value (<=0 to quit):\n");
scanf("%d", &sec);
}
return 0;
}
